using System;
using System.Diagnostics;
using System.IO;
using System.Text.RegularExpressions;
using UnityEngine;
#nullable enable
namespace Connector
{
    class WindowsPlatformSpecific : IPlatformSpecific
    {
        Process? process;

        public void Start(DeviceManager deviceManager)
        {

            process = new Process();
            process.StartInfo.FileName = GetConnectorExeFilePath();
            process.StartInfo.UseShellExecute = false;
            process.StartInfo.RedirectStandardOutput = true;
            process.StartInfo.RedirectStandardError = true;
            process.StartInfo.RedirectStandardInput = true;
            if (Application.isEditor)
            {
                process.StartInfo.CreateNoWindow = false;
            }
            else
            {
                process.StartInfo.CreateNoWindow = true;
            }
            // keep terminal window open in case Unity doesn't stop the process

            // process.OutputDataReceived += OnMessage;
            process.OutputDataReceived += (sender, args) =>
            {
                // end of stream reached, backend has stopped
                if (args.Data == null)
                    return;

                deviceManager.OnMessage(args.Data);
            };
            process.ErrorDataReceived += (sender, args) => deviceManager.RaiseError(new Exception(args.Data));

            process.Start();

            process.BeginOutputReadLine();
            process.BeginErrorReadLine();
        }

        public void Stop()
        {
            if (process != null && !process.HasExited)
            {
                process.Kill();
                process.WaitForExit();
                process = null;
            }
        }

        public void SendMessage(string serializedMessage)
        {
            if (process == null || process.HasExited)
                throw new Exception("Backend is not running");

            process.StandardInput.WriteLine(serializedMessage);
        }
        public string? GetConnectorExeFilePath()
        {
            var files = Directory.GetFiles(Application.streamingAssetsPath);
            foreach (var file in files)
            {
                string fileName = Path.GetFileName(file);
                if (Regex.IsMatch(fileName, "Connector.*exe") && !fileName.Contains(".meta"))
                {
                    return file;
                }
            }
            return null;
        }
    }
}

using Connector;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public interface IPlatformSpecific
{
    void SendMessage(string serializedMessage);
    void Start(DeviceManager deviceManager);
    void Stop();
}

using UnityEngine;
namespace Connector
{
    class AndroidPlatformSpecific : IPlatformSpecific
    {

        AndroidJavaObject main;
        class MessageListener : AndroidJavaProxy
        {
            DeviceManager deviceManager;
            public MessageListener(DeviceManager deviceManager) : base("com.cynteract.connector.MessageListener")
            {
                this.deviceManager = deviceManager;
            }

            public void onMessage(string message)
            {
                deviceManager.OnMessage(message);
            }
        }

        public void Start(DeviceManager deviceManager)
        {
            AndroidJavaClass unityPlayerClass = new AndroidJavaClass("com.unity3d.player.UnityPlayer");
            AndroidJavaObject unityActivity = unityPlayerClass.GetStatic<AndroidJavaObject>("currentActivity");

            // add message listener that
            main = new AndroidJavaObject("com.cynteract.connector.Main", new MessageListener(deviceManager));
            main.Call("initialize", unityActivity);
        }

        public void Stop()
        {
            if (main == null)
            {
                Debug.LogWarning("Connector not running, nothing to stop");
                return;
            }
            AndroidJavaClass unityPlayerClass = new AndroidJavaClass("com.unity3d.player.UnityPlayer");
            AndroidJavaObject unityActivity = unityPlayerClass.GetStatic<AndroidJavaObject>("currentActivity");
            main.Call("close", unityActivity);
        }

        public void SendMessage(string serializedMessage)
        {
            main.Call("sendMessage", serializedMessage);
        }
    }
}

